import org.junit.jupiter.api.function.Executable;

/**
 * Query rendering round trip for the GH-6193 extension functions: a query using one function of every family, written
 * once with full IRIs and once with prefixed names, must render (legacy and IR renderer) to SPARQL that re-parses to a
 * query with the same function calls and, where the function is evaluable without a store, the same results.
 * <p>
 * Magic properties are plain statement patterns with RDF collections until the evaluation-time optimizer rewrites them,
 * so for them the round trip compares the statement pattern predicates. The {@code geox:} functions are not on this
 * module's classpath and are only rendered, not evaluated. Custom aggregates ({@code agg:}) are rendered and re-parsed
 * but not evaluated here; {@link CustomAggregateRenderingTest} covers their rendering in depth.
 */
class ExtensionFunctionRenderRoundTripTest {

	private static final String PREFIXES = "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n"
			+ "PREFIX mathf: <http://rdf4j.org/function/math#>\n"
			+ "PREFIX strf: <http://rdf4j.org/function/string#>\n"
			+ "PREFIX dtf: <http://rdf4j.org/function/datetime#>\n"
			+ "PREFIX agg: <http://rdf4j.org/aggregate#>\n"
			+ "PREFIX winf: <http://rdf4j.org/function/window#>\n"
			+ "PREFIX textf: <http://rdf4j.org/function/text#>\n"
			+ "PREFIX jsonf: <http://rdf4j.org/function/json#>\n"
			+ "PREFIX arrf: <http://rdf4j.org/function/array#>\n"
			+ "PREFIX geox: <http://rdf4j.org/function/geo#>\n"
			+ "PREFIX bitf: <http://rdf4j.org/function/bitwise#>\n"
			+ "PREFIX encf: <http://rdf4j.org/function/encoding#>\n"
			+ "PREFIX miscf: <http://rdf4j.org/function/misc#>\n";

	private static final String VALUES = " WHERE { VALUES (?x ?s) { (4 \"ab,c\") (9 \"xyz\") } }";

	/** One query per family: name, prefixed form, IRI form and whether it is evaluable without a store. */
	private static final List<Family> FAMILIES = List.of(
			family("mathf", "SELECT ?x (mathf:round(mathf:sqrt(?x), 1) AS ?r)" + VALUES, true),
			family("strf", "SELECT ?x (strf:reverse(?s) AS ?r)" + VALUES, true),
			family("dtf", "SELECT ?x (dtf:dayOfYear(\"2024-03-05\"^^xsd:date) AS ?r)" + VALUES, true),
			family("agg", "SELECT (agg:median(?x) AS ?r)" + VALUES, false),
			family("winf", "SELECT ?x (winf:rank(winf:orderBy(winf:desc(?x))) AS ?r)" + VALUES, true),
			family("textf", "SELECT ?x (textf:levenshtein(?s, \"abc\") AS ?r)" + VALUES, true),
			family("jsonf", "SELECT ?x (jsonf:jsonValue('{\"k\":1}', \"$.k\") AS ?r)" + VALUES, true),
			family("arrf", "SELECT ?x (arrf:arrayLength(strf:split(?s, \",\")) AS ?r)" + VALUES, true),
			family("geox", "SELECT ?x (geox:area(?s) AS ?r)" + VALUES, false),
			family("bitf", "SELECT ?x (bitf:bitAnd(?x, 6) AS ?r)" + VALUES, true),
			family("encf", "SELECT ?x (encf:toHex(?s) AS ?r)" + VALUES, true),
			family("miscf", "SELECT ?x (miscf:nullIf(?x, 4) AS ?r)" + VALUES, true),
			family("magic property", "SELECT ?x ?p WHERE { VALUES ?x { 1 } (\"a,b\" \",\") strf:split (?p) }",
					true));

	private record Family(String name, String prefixed, String iriForm, boolean evaluable) {
	}

	private static Family family(String name, String prefixed, boolean evaluable) {
		return new Family(name, prefixed, expandPrefixes(prefixed), evaluable);
	}

	/** Rewrites every {@code prefix:local} of the extension namespaces into its {@code <IRI>} form. */
	private static String expandPrefixes(String query) {
		String iriForm = query;
		for (String line : PREFIXES.split("\n")) {
			String prefix = line.substring("PREFIX ".length(), line.indexOf(':') + 1);
			String namespace = line.substring(line.indexOf('<') + 1, line.indexOf('>'));
			if (prefix.equals("xsd:")) {
				continue;
			}
			iriForm = iriForm.replaceAll("\\b" + prefix + "([A-Za-z]+)", "<" + namespace + "$1>");
		}
		assertThat(iriForm).as("IRI form differs from the prefixed form").isNotEqualTo(query);
		return iriForm;
	}

	@Test
	void renderRoundTripPreservesFunctionCallsOfEveryFamily() {
		List<Executable> cases = new ArrayList<>();
		for (Family family : FAMILIES) {
			for (String query : List.of(family.prefixed(), family.iriForm())) {
				for (boolean legacy : List.of(false, true)) {
					cases.add(() -> assertRoundTrip(family.name(), query, legacy, family.evaluable()));
				}
			}
		}
		assertAll(cases);
	}

	private static void assertRoundTrip(String family, String query, boolean legacy, boolean evaluable)
			throws Exception {
		ParsedQuery original = parse(query);
		String rendered = render(original, legacy);
		String context = family + " / " + (legacy ? "legacy" : "IR") + " renderer\n" + query + "\n" + rendered;
		ParsedQuery reparsed;
		try {
			reparsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, rendered, null);
		} catch (MalformedQueryException e) {
			throw new AssertionError(context + "\nrendered query does not parse: " + e.getMessage(), e);
		}
		assertThat(functionIris(reparsed.getTupleExpr())).as(context + "\nfunction calls")
				.isEqualTo(functionIris(original.getTupleExpr()));
		// blank node labels of RDF collections are regenerated on every parse, so they are masked for the fixpoint
		assertThat(maskBlankNodes(render(reparsed, legacy))).as(context + "\nrender fixpoint")
				.isEqualTo(maskBlankNodes(rendered));
		if (evaluable) {
			assertThat(evaluate(reparsed.getTupleExpr())).as(context + "\nresults")
					.containsExactlyElementsOf(evaluate(original.getTupleExpr()));
		}
	}

	private static String maskBlankNodes(String rendered) {
		return rendered.replaceAll("_:[A-Za-z0-9_]+", "_:b");
	}

	/** Multiset (sorted list) of every scalar, aggregate and window function IRI plus statement predicates. */
	private static List<String> functionIris(TupleExpr expression) {
		List<String> iris = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(FunctionCall node) {
				iris.add("function " + node.getURI());
				super.meet(node);
			}

			@Override
			public void meet(AggregateFunctionCall node) {
				iris.add("aggregate " + node.getIRI());
				super.meet(node);
			}

			@Override
			public void meet(WindowFunctionCall node) {
				iris.add("window " + node.getURI());
				super.meet(node);
			}

			@Override
			public void meet(StatementPattern node) {
				if (node.getPredicateVar().hasValue()) {
					iris.add("predicate " + node.getPredicateVar().getValue());
				}
				super.meet(node);
			}
		});
		iris.sort(null);
		assertThat(iris).as("the query must contain at least one extension function").isNotEmpty();
		return iris;
	}

	private static ParsedQuery parse(String query) {
		return QueryParserUtil.parseQuery(QueryLanguage.SPARQL, PREFIXES + query, null);
	}

	private static String render(ParsedQuery query, boolean legacy) throws Exception {
		if (legacy) {
			return new SPARQLQueryRenderer().render(query, QueryParseOptions.DEFAULT);
		}
		Config config = new Config();
		config.parseOptions = QueryParseOptions.DEFAULT;
		return new TupleExprIRRenderer(config).render(query.getTupleExpr(), null);
	}

	private static List<Map<String, Value>> evaluate(TupleExpr expression) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new EmptyIteration<>();
			}

			@Override
			public ValueFactory getValueFactory() {
				return SimpleValueFactory.getInstance();
			}
		};
		List<Map<String, Value>> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = new DefaultEvaluationStrategy(source, null)
				.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				Map<String, Value> row = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					if (bindings.hasBinding(name)) {
						row.put(name, bindings.getValue(name));
					}
				}
				rows.add(row);
			}
		}
		return rows;
	}
}
